def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Recolor any uniform full row or column.
    for r in range(h):
        if all(grid[r][c] == grid[r][0] for c in range(w)):
            for c in range(w):
                out[r][c] = 2

    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            for r in range(h):
                out[r][c] = 2

    return out
